        if self.files_deleted > 10000:
            self.price = 0.01
        else:
            self.price = 0.1
        print(f"Files deleted: {self.files_deleted}")
        print(f"Price: {self.price}")
        payment = input("Do you want to pay? (yes/no): ")
        if payment.lower() == "yes":
            if self.price > 0:
                payment = input("Please pay: ")
                if payment.lower() == "yes":
                    self.price = 0
                    print("Payment successful!")
                else:
                    print("Payment failed. File not deleted.")
            else:
                print("No payment required.")
        else:
            print("File not deleted.")
